// Some portions generated by Claude
import { useEffect, useId, useLayoutEffect, useRef, type MouseEvent, type RefObject, type SyntheticEvent } from "react";
import type { ViewMode } from "./explorer-types.ts";
import { Icon } from "./icons.tsx";
import { isApplePlatform } from "./graph-viewport.ts";
import { graphGuide } from "./explorer-help.ts";
import { GuideContent, HelpTip } from "./help-tip.tsx";
import { fitToolbar, type ToolbarFit } from "./toolbar-fit.ts";

/** Undo and redo as the platform writes them (⌘ on Apple platforms, Ctrl elsewhere). */
const HISTORY_KEYS = isApplePlatform()
  ? { undo: { shown: "⌘Z", aria: "Meta+Z" }, redo: { shown: "⇧⌘Z", aria: "Meta+Shift+Z" } }
  : { undo: { shown: "Ctrl+Z", aria: "Control+Z" }, redo: { shown: "Ctrl+Shift+Z", aria: "Control+Shift+Z" } };

/** The gestures and keys of the graph, as this platform names them (the help popover beside full screen). */
const GUIDE = graphGuide(isApplePlatform());

/** One row of the Layout or Tools menu; `description` is a line under the label saying what it does. */
export type ToolbarMenuItem = {
  label: string;
  description?: string;
  onSelect: () => void;
  disabled?: boolean;
  pressed?: boolean;
  danger?: boolean;
  title?: string;
};

export type ToolbarMenuRefs = {
  view: RefObject<HTMLDetailsElement | null>;
  layout: RefObject<HTMLDetailsElement | null>;
  tools: RefObject<HTMLDetailsElement | null>;
};

export type ExplorerToolbarProps = {
  queryPanelOpen: boolean;
  onToggleQueryPanel: () => void;
  viewMode: ViewMode;
  recommendedView: ViewMode;
  onViewMode: (mode: ViewMode) => void;
  canUndo: boolean;
  canRedo: boolean;
  onUndo: () => void;
  onRedo: () => void;
  hasNodes: boolean;
  hasLinks: boolean;
  showValues: boolean;
  onToggleValues: () => void;
  showAllEdgeLabels: boolean;
  onToggleLabels: () => void;
  filtersOpen: boolean;
  filterCount: number;
  onToggleFilters: () => void;
  layoutBusy: boolean;
  /** What the layouts apply to, when not the whole graph (a selection). */
  layoutNote?: string;
  layoutItems: readonly ToolbarMenuItem[];
  toolItems: readonly ToolbarMenuItem[];
  isFullscreen: boolean;
  onToggleFullscreen: () => void;
  menuRefs: ToolbarMenuRefs;
  /** A toolbar menu opened: the node menu closes. */
  onMenuOpen: () => void;
};

/** The views of the loaded graph, as the View menu offers them: the mode, its name and what it shows. */
const VIEWS: ReadonlyArray<[ViewMode, string, string]> = [
  ["graph", "Graph", "Resources and the links between them"],
  ["table", "Triples", "Every statement as a row"],
  ["cards", "Cards", "One card per resource"],
  ["matrix", "Matrix", "Connection density"],
  ["timeline", "Timeline", "Dates and events"],
  ["map", "Map", "Places and coordinates"],
  ["chart", "Chart", "Value frequencies"],
];

/** A choice in a popover menu closes the menu. */
function closeOnChoice(event: MouseEvent<HTMLDivElement>) {
  if ((event.target as Element).closest("button")) event.currentTarget.parentElement?.removeAttribute("open");
}

/**
 * The explorer's one-row toolbar: query editor, the View menu, history, what the graph shows, layout, tools, full
 * screen. In its compact form (a phone) history and the Values and Labels switches are rows of the Tools menu.
 */
export function ExplorerToolbar(props: ExplorerToolbarProps) {
  const { menuRefs, onMenuOpen, viewMode, recommendedView } = props;
  // Only one toolbar menu is open at a time.
  const opened = (own: keyof ToolbarMenuRefs) => (event: SyntheticEvent<HTMLDetailsElement>) => {
    if (!event.currentTarget.open) return;
    (Object.keys(menuRefs) as Array<keyof ToolbarMenuRefs>).forEach((key) => {
      const menu = menuRefs[key].current;
      if (key !== own && menu) menu.open = false;
    });
    onMenuOpen();
  };
  const currentView = VIEWS.find(([mode]) => mode === viewMode)?.[1] ?? "Graph";
  const otherRecommended = recommendedView !== viewMode && recommendedView !== "graph";
  // In the compact toolbar these buttons are rows of the Tools menu (graph-explorer.css shows one or the other).
  const compactItems: ToolbarMenuItem[] = [
    { label: "Undo", description: `The last graph change (${HISTORY_KEYS.undo.shown})`, onSelect: props.onUndo,
      disabled: !props.canUndo },
    { label: "Redo", description: `The last undone graph change (${HISTORY_KEYS.redo.shown})`, onSelect: props.onRedo,
      disabled: !props.canRedo },
    { label: "Show values and types as nodes", onSelect: props.onToggleValues, pressed: props.showValues,
      disabled: !props.hasNodes },
    { label: "Show all relation labels", onSelect: props.onToggleLabels, pressed: props.showAllEdgeLabels,
      disabled: !props.hasLinks },
  ];
  // Labels while everything fits on one row with them, then icons, then the compact form (toolbar-fit.ts): measured
  // after every render, since a filter count or the chosen view's name changes the width, and whenever the panel resizes.
  const toolbarRef = useRef<HTMLDivElement>(null);
  const fitRef = useRef<ToolbarFit>({ level: 0, widths: [] });
  useLayoutEffect(() => {
    if (toolbarRef.current) fitRef.current = fitToolbar(toolbarRef.current, fitRef.current);
  });
  useEffect(() => {
    const bar = toolbarRef.current;
    // The panel around it: showing or hiding the labels changes the toolbar's own height, not the panel's width.
    const panel = bar?.parentElement;
    if (!bar || !panel || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      fitRef.current = fitToolbar(bar, fitRef.current);
    });
    observer.observe(panel);
    return () => observer.disconnect();
  }, []);
  return (
    <div className="graph-toolbar" ref={toolbarRef} data-fit="labels">
      <button
        className="workbench-action workbench-action--secondary"
        type="button"
        aria-label="Query editor"
        aria-expanded={props.queryPanelOpen}
        aria-controls="query-workspace"
        title={props.queryPanelOpen ? "Close the query editor" : "Open the query editor"}
        onClick={props.onToggleQueryPanel}
      >
        <Icon name="query" />
        <span className="toolbar-label">Query editor</span>
      </button>
      <details ref={menuRefs.view} className="view-menu" onToggle={opened("view")}>
        <summary
          aria-label={`View: ${currentView}`}
          title={otherRecommended ? "Choose a view · another view is recommended for this data" : "Choose a view"}
          data-recommended={otherRecommended ? "true" : undefined}
        >
          {currentView}
          <Icon name="chevron" className="workbench-disclosure-chevron" />
        </summary>
        <div className="view-menu-popover" onClick={closeOnChoice}>
          {VIEWS.map(([mode, label, description]) => (
            <button
              key={mode}
              type="button"
              data-view={mode}
              aria-current={viewMode === mode ? "true" : undefined}
              className={viewMode === mode ? "is-active" : ""}
              onClick={() => props.onViewMode(mode)}
            >
              <span>{label}</span>
              <small>
                {recommendedView === mode && mode !== "graph" ? "Recommended · " : ""}
                {description}
              </small>
            </button>
          ))}
        </div>
      </details>
      <div className="toolbar-actions">
        <div className="toolbar-group history-controls" role="group" aria-label="Workspace history">
          <button
            className="workbench-action workbench-action--ghost workbench-action--icon"
            type="button"
            aria-label="Undo the last graph change"
            aria-keyshortcuts={HISTORY_KEYS.undo.aria}
            title={`Undo (${HISTORY_KEYS.undo.shown})`}
            disabled={!props.canUndo}
            onClick={props.onUndo}
          >
            <Icon name="undo" />
          </button>
          <button
            className="workbench-action workbench-action--ghost workbench-action--icon"
            type="button"
            aria-label="Redo the last undone graph change"
            aria-keyshortcuts={HISTORY_KEYS.redo.aria}
            title={`Redo (${HISTORY_KEYS.redo.shown})`}
            disabled={!props.canRedo}
            onClick={props.onRedo}
          >
            <Icon name="redo" />
          </button>
        </div>
        <div className="toolbar-group panel-toggles" role="group" aria-label="What the graph shows">
          <button
            className="workbench-action workbench-action--secondary values-toggle"
            type="button"
            aria-label="Show values and types as nodes"
            title="Show values and types as nodes"
            aria-pressed={props.showValues}
            onClick={props.onToggleValues}
            disabled={!props.hasNodes}
          >
            <Icon name="values" />
            <span className="toolbar-label">Values</span>
          </button>
          <button
            className="workbench-action workbench-action--secondary labels-toggle"
            type="button"
            aria-label="Show all relation labels"
            title="Show all relation labels"
            aria-pressed={props.showAllEdgeLabels}
            onClick={props.onToggleLabels}
            disabled={!props.hasLinks}
          >
            <Icon name="labels" />
            <span className="toolbar-label">Labels</span>
          </button>
          <button
            className="workbench-action workbench-action--secondary"
            type="button"
            aria-label="Filter graph nodes by kind, datatype, language, type, or predicate values"
            title="Filter graph nodes"
            aria-expanded={props.filtersOpen}
            aria-controls="graph-filter-sidebar"
            aria-pressed={props.filtersOpen || props.filterCount > 0}
            onClick={props.onToggleFilters}
            disabled={!props.hasNodes}
          >
            <Icon name="filter" />
            <span className="toolbar-label">Filters</span>
            {props.filterCount ? <span className="toolbar-count">{props.filterCount}</span> : null}
          </button>
        </div>
        <details className="toolbar-menu layout-menu" ref={menuRefs.layout} onToggle={opened("layout")}>
          <summary
            aria-label="Choose graph layout"
            title={props.layoutBusy ? "Layout · organizing…" : "Layout"}
            aria-busy={props.layoutBusy}
          >
            <Icon name="layout" className={props.layoutBusy ? "is-working" : undefined} />
            <span className="toolbar-label">Layout</span>
            <Icon name="chevron" className="workbench-disclosure-chevron" />
          </summary>
          <div className="toolbar-menu-popover" onClick={closeOnChoice}>
            {props.layoutNote ? (
              <div className="toolbar-menu-note" role="note">
                {props.layoutNote}
              </div>
            ) : null}
            {props.layoutItems.map((item) => (
              <MenuItem key={item.label} item={item} strong />
            ))}
          </div>
        </details>
        <details ref={menuRefs.tools} className="toolbar-menu" onToggle={opened("tools")}>
          <summary aria-label="Open workspace tools" title="Tools">
            <Icon name="tools" />
            <span className="toolbar-label">Tools</span>
            <Icon name="chevron" className="workbench-disclosure-chevron" />
          </summary>
          <div className="toolbar-menu-popover" onClick={closeOnChoice}>
            {compactItems.map((item) => (
              <MenuItem key={item.label} item={item} className="toolbar-compact-item" />
            ))}
            <div className="toolbar-compact-item toolbar-menu-separator" role="separator" />
            {props.toolItems.map((item) => (
              <MenuItem key={item.label} item={item} />
            ))}
          </div>
        </details>
        <HelpTip label="How to use the graph" align="end" wide>
          <GuideContent sections={GUIDE} />
        </HelpTip>
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label={props.isFullscreen ? "Exit full screen" : "Enter full screen"}
          title={props.isFullscreen ? "Exit full screen" : "Full screen"}
          aria-pressed={props.isFullscreen}
          onClick={props.onToggleFullscreen}
        >
          <Icon name={props.isFullscreen ? "exit-full-screen" : "full-screen"} />
        </button>
      </div>
    </div>
  );
}

/** A menu row: the label names it; a description, shown under the label, describes it without renaming it. */
function MenuItem({ item, strong = false, className }: { item: ToolbarMenuItem; strong?: boolean; className?: string }) {
  const descriptionId = useId();
  return (
    <button
      type="button"
      className={[item.danger ? "danger-action" : "", className ?? ""].filter(Boolean).join(" ") || undefined}
      aria-pressed={item.pressed}
      aria-label={item.description ? item.label : undefined}
      aria-describedby={item.description ? descriptionId : undefined}
      title={item.title}
      disabled={item.disabled}
      onClick={item.onSelect}
    >
      {strong ? <strong>{item.label}</strong> : item.description ? <span>{item.label}</span> : item.label}
      {item.description ? <small id={descriptionId}>{item.description}</small> : null}
    </button>
  );
}
